import {sheetSVG,WIDTH,HEIGHT} from './sheet.mjs';
import {richTextSVG,bindingValue,fontFamilies} from './text-editor.js';
export function rotatedBounds(b){const angle=(b.rotation||0)*Math.PI/180,c=Math.abs(Math.cos(angle)),s=Math.abs(Math.sin(angle)),w=b.w*c+b.h*s,h=b.w*s+b.h*c;return {x:b.x+(b.w-w)/2,y:b.y+(b.h-h)/2,w,h};}
export function measureOverflow(b,d){const body=bindingValue(b,d);if(!body||!['text','ability','equipment','profile','ritualPart'].includes(b.type))return null;const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),measure=(t,n,f,bold)=>{ctx.font=`${bold?'bold ':''}${n}px ${f}`;return ctx.measureText(t).width;};const offset=b.part==='content'||b.type==='ritualPart'?0:48,result=richTextSVG(body,b,b.w,b.h-offset,measure);return {...result,height:result.height+offset};}
export function preflight(d,{fontAvailable=()=>true}={}){const warnings=[];for(const b of d.blocks){if(!b.visible)continue;const rect=rotatedBounds(b);if(rect.x<0||rect.y<0||rect.x+rect.w>WIDTH||rect.y+rect.h>HEIGHT)warnings.push({id:b.id,message:'Parte do elemento está fora da página e não será exportada.'});if(['portrait','image'].includes(b.type)&&!(b.type==='portrait'?d.portrait:b.image))warnings.push({id:b.id,message:'Imagem ausente.'});const overflow=measureOverflow(b,d);if(overflow?.overflow)warnings.push({id:b.id,message:b.autoFit!==false?'O texto precisa de ajuste automático para caber.':'Texto ultrapassa a altura do bloco.'});if(b.type==='ability'&&!d.abilities.some(a=>a.id===b.ref)||b.type==='ritualPart'&&!d.rituals.some(r=>r.id===b.ref))warnings.push({id:b.id,message:'Componente sem informação vinculada.'});const family=b.textStyle?.family;if(family&&!fontAvailable(family))warnings.push({id:b.id,message:'Fonte indisponível: '+family});}return warnings;}
export function rasterSize(width=1920){width=Math.max(320,Math.min(8000,Math.round(Number(width)||1920)));return {width,height:Math.round(width*HEIGHT/WIDTH)};}
// A small, dependency-free PDF writer. The rendered sheet is embedded as a high-quality JPEG.
export function pdfBytes(jpeg,pixelWidth,pixelHeight,{page='A4',orientation='landscape',margin=10}={}){const sizes={A4:[595.276,841.89],A3:[841.89,1190.551],Letter:[612,792],sheet:[pixelWidth*.375,pixelHeight*.375]};let [w,h]=sizes[page]||sizes.A4;if(orientation==='landscape'&&w<h||orientation==='portrait'&&w>h)[w,h]=[h,w];const m=Math.max(0,Math.min(80,Number(margin)||0))*72/25.4,ratio=Math.min((w-2*m)/pixelWidth,(h-2*m)/pixelHeight),iw=pixelWidth*ratio,ih=pixelHeight*ratio,x=(w-iw)/2,y=(h-ih)/2,enc=new TextEncoder(),chunks=[],offsets=[0];let length=0;const add=x=>{const bytes=typeof x==='string'?enc.encode(x):x;chunks.push(bytes);length+=bytes.length;};const object=(n,body)=>{offsets[n]=length;add(`${n} 0 obj\n`);add(body);add('\nendobj\n');};add('%PDF-1.4\n');object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');object(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] /Resources << /XObject << /Sheet 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=length;add(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${pixelWidth} /Height ${pixelHeight} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);add(jpeg);add('\nendstream\nendobj\n');const content=`q ${iw} 0 0 ${ih} ${x} ${y} cm /Sheet Do Q`;object(5,`<< /Length ${enc.encode(content).length} >>\nstream\n${content}\nendstream`);const xref=length;add('xref\n0 6\n0000000000 65535 f \n');for(let n=1;n<=5;n++)add(String(offsets[n]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);const output=new Uint8Array(length);let at=0;for(const chunk of chunks){output.set(chunk,at);at+=chunk.length;}return output;}
export async function renderExport(d,skills,cache,imageData,options={}){for(const b of d.blocks)if(b.image)await imageData(b.image);if(d.portrait)await imageData(d.portrait);await document.fonts?.ready;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">${sheetSVG(d,skills,cache,{transparent:!!options.transparent})}</svg>`;return svg;}
export async function rasterize(svg,width=3840){const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();image.src=url;await image.decode();const size=rasterSize(width),canvas=document.createElement('canvas');canvas.width=size.width;canvas.height=size.height;canvas.getContext('2d').drawImage(image,0,0,size.width,size.height);return canvas;}finally{URL.revokeObjectURL(url);}}
export function installExports(E){let options={width:3840,transparent:false,page:'A4',orientation:'landscape',margin:10};const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));function showPreflight(){const warnings=preflight(E.doc,{fontAvailable:f=>fontFamilies.includes(f)||[...document.fonts].some(face=>face.family===f&&face.status==='loaded')});E.modal('Conferência antes de exportar',`<p class="subtle">${warnings.length?warnings.length+' aviso(s). Você pode exportar mesmo assim.':'Nenhum problema encontrado.'}</p>${warnings.map(w=>`<div class="version-item">${esc(E.doc.blocks.find(b=>b.id===w.id)?.title)}: ${esc(w.message)} <button data-locate="${w.id}">Localizar</button></div>`).join('')}`,`<button data-action="close-modal" class="primary">Concluir</button>`);document.querySelectorAll('[data-locate]').forEach(el=>el.onclick=()=>{E.closeModal();E.select(el.dataset.locate,true,false,true);});}
 function showExportOptions(){E.modal('Exportação de alta qualidade',`<div class="pro-panel"><p class="subtle">PNG e PDF usam a mesma composição do SVG. O PDF preserva a aparência como imagem de alta resolução.</p><label>Resolução<select id="exportResolution"><option value="1920">Padrão · 1920 × 1431</option><option value="3840" selected>Alta · 3840 × 2862</option><option value="custom">Personalizada</option></select></label><label>Largura personalizada (320–8000 px)<input id="exportWidth" type="number" min="320" max="8000" value="${options.width}"></label><label><input id="exportTransparent" type="checkbox" ${options.transparent?'checked':''}> Fundo transparente (PNG e SVG)</label><div class="compact-grid"><label>Papel PDF<select id="pdfPage">${['A4','A3','Letter','sheet'].map(k=>`<option ${options.page===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Orientação<select id="pdfOrientation"><option value="landscape">Paisagem</option><option value="portrait">Retrato</option></select></label><label>Margens (mm)<input id="pdfMargin" type="number" value="${options.margin}" min="0" max="80"></label></div><div class="pro-toolbar"><button id="preflightExport">Conferir ficha</button>${['png','svg','pdf','json'].map(t=>`<button class="pro-button" data-final-export="${t}">${t.toUpperCase()}</button>`).join('')}</div></div>`,`<button data-action="close-modal" class="quiet">Fechar</button>`);$('#preflightExport').onclick=showPreflight;document.querySelectorAll('[data-final-export]').forEach(el=>el.onclick=()=>{options={width:$('#exportResolution').value==='custom'?Number($('#exportWidth').value):Number($('#exportResolution').value),transparent:$('#exportTransparent').checked,page:$('#pdfPage').value,orientation:$('#pdfOrientation').value,margin:Number($('#pdfMargin').value)};exportDoc(el.dataset.finalExport);});}
 async function exportDoc(type){$('#exportMenu').hidden=true;document.body.classList.add('busy');try{await E.save();const name=E.doc.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').toLowerCase();if(type==='print'){window.print();return;}if(type==='json'){const portable=structuredClone(E.doc);portable.schemaVersion=2;portable.portrait=await E.imageData(portable.portrait);for(const b of portable.blocks)if(b.image)b.image=await E.imageData(b.image);E.download(new Blob([JSON.stringify(portable,null,2)],{type:'application/json'}),name+'.catastrophe.json');return;}
 const svg=await renderExport(E.doc,E.source.skills,E.imageCache,E.imageData,{...options,transparent:type==='pdf'?false:options.transparent});if(type==='svg'){E.download(new Blob([svg],{type:'image/svg+xml'}),name+'.svg');return;}const canvas=await rasterize(svg,options.width);if(type==='pdf'){const jpeg=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.98));if(!jpeg)throw Error('Não foi possível gerar o PDF.');E.download(new Blob([pdfBytes(new Uint8Array(await jpeg.arrayBuffer()),canvas.width,canvas.height,options)],{type:'application/pdf'}),name+'.pdf');}else {const png=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!png)throw Error('Não foi possível gerar a imagem.');E.download(png,name+'.png');}E.toast('Arquivo exportado.');}catch(err){E.toast('Erro ao exportar: '+err.message);}finally{document.body.classList.remove('busy');}}
 return {exportDoc,showPreflight,showExportOptions};}
